{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Cadazolid, the highest-transfer analogue (0.9725), showed very low oral bioavailability in healthy subjects, with high CL/F and V/F consistent with F well below 20%; this directly supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ergotamine absolute oral bioavailability was less than 1% in patients, a direct threshold-relevant measurement; the high transfer score indicates relevance to the query's rigid basic CNS scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tetrabenazine, a rigid basic ketone-containing CNS drug, had mean systemic availability of 0.049 after oral dosing, directly below the 20% threshold; high transferability supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "MK-458, a phenolic rigid amine with a morphinan-like scaffold, had absolute oral bioavailability of approximately 5% in patients, directly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Lumateperone, a rigid basic CNS drug, had absolute oral bioavailability of approximately 4.4% in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "UK-224,671 had very low oral bioavailability (5-10%) due to poor absorption and P-gp efflux; the rifampin co-treatment condition would be expected to worsen, not improve, such liabilities.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental evidence points to very low oral bioavailability (<20%) for rigid, basic, phenolic/ketone-containing CNS drugs, and rifampin co-treatment would be expected to further reduce bioavailability via enzyme/transporter induction. Therefore low F is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query under rifampin co-treatment.",
    "The magnitude of rifampin's effect on UGT/P-gp-mediated first-pass metabolism for this specific morphinan is unknown.",
    "Baseline oral bioavailability of the query without rifampin may be moderate, but the threshold under co-treatment is not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

